// ---- Observable-builtin replacements ----
function DOMsvg(width, height) {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  svg.setAttribute("xmlns:xlink", "http://www.w3.org/1999/xlink");
  svg.setAttribute("width", width);
  svg.setAttribute("height", height);
  svg.setAttribute("viewBox", "0 0 " + width + " " + height);
  return svg;
}

// Minimal Observable-style html tagged template: returns the first element child.
function html(strings, ...values) {
  let str = strings[0];
  for (let i = 0; i < values.length; i++) str += values[i] + strings[i + 1];
  const tpl = document.createElement("template");
  tpl.innerHTML = str.trim();
  return tpl.content.firstElementChild;
}

// A raw (pre-project-file) Mapa settings object -- top-level projection/basemap/clipping/bounds/…
// -- vs. an Atlas project object -- view/export/frames/points/polys. Shared by the editor (view-only
// import of old configs) and the visual-regression harness (test/harness.html), which must branch
// on fixture shape exactly the same way the editor does.
export function looksLikeRawConfig(o) {
  if (!o || typeof o !== "object") return false;
  const atlas = ["view", "export", "frames", "points", "polys"].some((k) => k in o);
  const mapa = ["projection", "basemap", "clipping", "bounds", "scalebar"].some((k) => k in o);
  return mapa && !atlas;
}

// The [lng, lat] the tilted geoSatellite render actually centres on (its authored longitude/latitude
// is the NADIR — the view centres forward of it). Build the same projection the export uses and
// invert the canvas centre. Used to seed the MapLibre nav pane on the true view centre, not the nadir.
export function satelliteViewCenter({ longitude, latitude, altitude, rotation, tilt, fieldOfView, width = 1000, height }) {
  const R = 6371, rad = Math.PI / 180;
  const numPixelsY = height || width;
  const dZ = altitude * Math.cos(tilt * rad), dY = altitude * Math.sin(tilt * rad);
  const visibleYextent = 2 * dZ * Math.tan(0.5 * fieldOfView * rad);
  const scale = R * numPixelsY / visibleYextent;
  const yShift = dY * numPixelsY / visibleYextent;
  const proj = d3
    .geoSatellite()
    .scale(scale)
    .translate([width / 2, yShift + numPixelsY / 2])
    .rotate([-longitude, -latitude, rotation])
    .tilt(tilt)
    .distance(1 + altitude / R)
    .precision(0.1);
  const c = proj.invert([width / 2, numPixelsY / 2]);
  return c && Number.isFinite(c[0]) && Number.isFinite(c[1]) ? c : [longitude, latitude];
}

// The same d3.geoSatellite the export uses, returned for hit-testing point visibility
// (project a [lng,lat] and check it lands inside [0,width]x[0,height]). Mirrors satelliteViewCenter.
export function satelliteProjector({ longitude, latitude, altitude, rotation, tilt, fieldOfView, width = 1000, height }) {
  const R = 6371, rad = Math.PI / 180;
  const numPixelsY = height || width;
  const dZ = altitude * Math.cos(tilt * rad), dY = altitude * Math.sin(tilt * rad);
  const visibleYextent = 2 * dZ * Math.tan(0.5 * fieldOfView * rad);
  const scale = R * numPixelsY / visibleYextent;
  const yShift = dY * numPixelsY / visibleYextent;
  return d3
    .geoSatellite()
    .scale(scale)
    .translate([width / 2, yShift + numPixelsY / 2])
    .rotate([-longitude, -latitude, rotation])
    .tilt(tilt)
    .distance(1 + altitude / R)
    .precision(0.1);
}

// Stream-transform helpers for the tilted-perspective (satellite) preclip, verbatim from
// @d3/satellite-explorer. geoPipeline composes clip stages (applied right-to-left);
// geoRotatePhi rotates the clip axis by the tilt so the horizon clip stays correct when tilted.
function geoPipeline(...transforms) {
  return (sink) => {
    for (let i = transforms.length - 1; i >= 0; --i) sink = transforms[i](sink);
    return sink;
  };
}
function geoRotatePhi(deltaPhi) {
  const cosDeltaPhi = Math.cos(deltaPhi), sinDeltaPhi = Math.sin(deltaPhi);
  return (sink) => ({
    point(lambda, phi) {
      const cosPhi = Math.cos(phi);
      const x = Math.cos(lambda) * cosPhi, y = Math.sin(lambda) * cosPhi, z = Math.sin(phi);
      const k = z * cosDeltaPhi + x * sinDeltaPhi;
      sink.point(Math.atan2(y, x * cosDeltaPhi - z * sinDeltaPhi), Math.asin(k));
    },
    lineStart() { sink.lineStart(); },
    lineEnd() { sink.lineEnd(); },
    polygonStart() { sink.polygonStart(); },
    polygonEnd() { sink.polygonEnd(); },
    sphere() { sink.sphere(); }
  });
}

