// ---- buildFilter (verbatim) ----
const buildFilter = function buildFilter({
  id,
  baseFrequency = 0.05,
  numOctaves = 4,
  scale = 4,
  seed = 0
}) {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  const filter = document.createElementNS(
    "http://www.w3.org/2000/svg",
    "filter"
  );
  filter.setAttribute("id", id);

  const turbulence = document.createElementNS(
    "http://www.w3.org/2000/svg",
    "feTurbulence"
  );
  turbulence.setAttribute("type", "fractalNoise");
  turbulence.setAttribute("baseFrequency", baseFrequency);
  turbulence.setAttribute("numOctaves", numOctaves);
  turbulence.setAttribute("seed", seed);

  const displacement = document.createElementNS(
    "http://www.w3.org/2000/svg",
    "feDisplacementMap"
  );
  displacement.setAttribute("in", "SourceGraphic");
  displacement.setAttribute("scale", scale);

  filter.appendChild(turbulence);
  filter.appendChild(displacement);
  return filter;
};


