const isoQ = function isoQ(input) {
  for (const country of countryData) {
    if (
      country.name === input ||
      country.ISO2 === input ||
      country.ISO3 === input
    ) {
      const result = { ...country };
      delete result[input];
      if (result) {
        return [[result.name, result.ISO2, result.ISO3]];
      }
    }
  }
};

