// ---- renderMap (the former Mapa class's constructor + render() getter, now a plain
// function). The class had exactly 2 call sites, both one-shot (new Mapa(cfg).render --
// construct once, read the getter once, never reused) -- a class bought nothing here.
// Redraw ONLY the annotation layer (#callouts) of an already-rendered map — the projection, size
// and every other layer stay as they are. For annotation edits, which used to re-render everything
// (basemap, data, tiles…). `annotations` = { show, data, editMode } in Mapa's shape
// (translate.atlasAnnotationsToMapa). Returns false when the SVG has no projection to reuse.
export function redrawAnnotations(svgNode, annotations, font) {
  const projection = svgNode && svgNode.projection;
  if (!projection) return false;
  const svg = d3.select(svgNode);
  let g = svg.select("#callouts");
  if (g.empty()) {
    // Not drawn by the last render (it had none): add it on top, inside the pan/zoom layer if any.
    const host = svg.select(":scope > g.zoom-layer");
    g = (host.empty() ? svg : host).append("g").attr("id", "callouts");
  }
  g.selectAll("*").remove();
  if (!annotations || annotations.show === false || !(annotations.data || []).length) return true;
  const width = +svgNode.getAttribute("width"), height = +svgNode.getAttribute("height");
  const { addAnnotations } = createLabelRenderer({
    gannotation: g, uid: "a", projection, width, height, path: d3.geoPath(projection), defs: svg.select("defs")
  });
  addAnnotations(annotations.data, annotations.editMode, g, font);
  return true;
}

export function renderMap(props) {
  const settings = buildSettings(props, defaultSettings());
    const defaults = settings.defaults;
    // Pattern fills: style.pattern "hatches" → <pattern> def whose <image> points at
    // <settings.patterns.folder>hatches.png. One def per (pattern, fill, size) combination,
    // written into <defs> at the end of the render.
    const patternDefs = new Map();
    const patternFill = (style) => {
      const name = String(style.pattern);
      // Tile size = the PNG's own pixel size × pattern-scale (default 1 = as made; 0.5 half), so a tile draws as it
      // was made. The page measures the PNGs (settings.patterns.sizes); unmeasured → settings.size square.
      const scale = +(style["pattern-scale"] ?? 1) || 1;
      const nat = settings.patterns.sizes?.[name];
      const [pw, ph] = nat ? [nat[0] * scale, nat[1] * scale] : [settings.patterns.size * scale, settings.patterns.size * scale];
      const size = `${+pw.toFixed(2)}x${+ph.toFixed(2)}`;
      const bg = style.fill && style.fill !== "none" ? style.fill : null;
      const op = style["pattern-opacity"] ?? 1;
      const bgOp = style["fill-opacity"] ?? 1;
      const id = `pat-${name}-${bg || "none"}-${bgOp}-${size}-${op}-${uid}`.replace(/[^\w-]/g, "-");
      if (!patternDefs.has(id)) patternDefs.set(id, { name, pw, ph, bg, bgOp, op });
      return `url(#${id})`;
    };
    const Layer = createLayer(defaults, patternFill);

    let uid = Math.random().toString(36).substr(2, 5);

    let margin = settings.clipping.margin;
    let width = settings.width;
    let height = settings.height;
    let basemap = settings.basemap;

    const sphere = { type: "Sphere" };
    const country = settings.basemap.land?.geometry ?? null;

    let projection = settings.projection.proj;

    if (settings.projection.type == "proj4") {
      function degreesToRadians(degrees) {
        return (degrees * Math.PI) / 180;
      }
      function radiansToDegrees(radians) {
        return (radians * 180) / Math.PI;
      }

      let check = settings.projection.proj.split(" ");
      for (let x of ["+x_0=0", "+y_0=0"]) {
        if (check.indexOf(x) == -1) {
          check.push(x);
        }
      }
      projection = check.join(" ");

      let projTarget = proj4(projection);
      let project4 = function (lambda, phi) {
        return projTarget.forward([lambda, phi].map(radiansToDegrees));
      };
      project4.invert = function (x, y) {
        return projTarget.inverse([x, y]).map(degreesToRadians);
      };

      projection = d3
        .geoProjection(project4)
        .fitExtent(
          [
            [0, 0],
            [width, height]
          ],
          settings.bounds.feature
        )
        .preclip(d3.geoClipAntimeridian);
    }

    if (settings.projection.type == "raw") {
      projection = settings.projection.proj;
    }

    if (settings.projection.type == "clip") {
      projection = settings.projection.proj.clipAngle(180);
    }

    if (settings.projection.type == "custom") {
      projection = settings.projection.proj
        .translate(settings.projection.translate || [width / 2, (height || width) / 2])
        .scale(settings.projection.scale)
        .center(settings.projection.center || [0, 0])
        .rotate(settings.projection.rotate)
        .tilt(settings.projection.tilt)
        .distance(settings.projection.distance)
        .precision(settings.projection.precision);
      // Tilted-perspective (satellite) horizon clip. Without it the far hemisphere projects
      // through the perspective singularity and sprays triangles across the whole frame. This is
      // the exact preclip from @d3/satellite-explorer: a horizon circle, tilt-corrected by
      // rotating the clip axis. When tilt is small enough that (P·cosθ) ≥ 1 the correction term
      // is undefined (NaN → falsy) and it degrades to the plain horizon circle, as in the source.
      const P = settings.projection.distance,
        tiltRad = (settings.projection.tilt || 0) * (Math.PI / 180);
      if (P > 1 && typeof d3.geoClipCircle === "function") {
        const alpha = Math.acos(P * Math.cos(tiltRad) * 0.999);
        const clipDistance = d3.geoClipCircle(Math.acos(1 / P) - 1e-6);
        projection.preclip(
          alpha
            ? geoPipeline(
                clipDistance,
                geoRotatePhi(Math.PI + tiltRad),
                d3.geoClipCircle(Math.PI - alpha - 1e-4),
                geoRotatePhi(-Math.PI - tiltRad)
              )
            : clipDistance
        );
      } else if (settings.projection.clipAngle) {
        projection.clipAngle(settings.projection.clipAngle);
      }
      // NOTE: no post-hoc re-centre. geoSatellite pins the rotate (nadir) point to translate, and the
      // caller's translate already carries the notebook yShift that puts the look-at at screen centre.
      // Re-centring on the nadir here would cancel that yShift and mis-frame the tilted view.
    }

    // Centre a FRAMED map on its viewport. fitSize/fitExtent only set translate+scale, never rotate — so
    // a projection whose framing depends on rotation stays at its default aspect and the region lands
    // off-centre (or, near the antimeridian, wraps split across the frame). Rotate to the frame centre
    // FIRST (the fit/height logic below then scales that view), unless the config supplied an explicit
    // rotate. Two regimes:
    //   • Azimuthal / perspective (orthographic, stereographic, gnomonic, azimuthal equal-area/equidistant)
    //     must FACE the target point → rotate [-lng, -lat].
    //   • Everything else (cylindrical, pseudocylindrical, conic, …) → rotate [-lng, 0]: recentre the
    //     central meridian on the frame (fixes Pacific/antimeridian framing) while keeping north up.
    //     Rotating their latitude would tilt them into an unexpected oblique aspect.
    // Custom (satellite) is skipped: it centres via its authored nadir from the pane.
    const AZIMUTHAL = [
      "geoOrthographic",
      "geoAzimuthalEqualArea",
      "geoAzimuthalEquidistant",
      "geoStereographic",
      "geoGnomonic"
    ];
    if (
      settings.bounds.bounder &&
      settings.bounds.feature &&
      settings.projection.type !== "custom" &&
      settings.projection.type !== "atlas" &&
      !settings.projection.rotate &&
      typeof projection.rotate === "function"
    ) {
      // Circular mean of the frame's corner longitudes (+ plain mean of latitudes). A linear longitude
      // mean puts an antimeridian-crossing frame (e.g. W=160,E=-160) near 0° — the wrong hemisphere; the
      // unit-vector mean wraps correctly.
      const ring = settings.bounds.feature.geometry.coordinates[0];
      let sx = 0, sy = 0, slat = 0, n = 0;
      for (const [lng, lat] of ring.slice(0, -1)) {
        const r = (lng * Math.PI) / 180;
        sx += Math.cos(r); sy += Math.sin(r); slat += lat; n++;
      }
      if (n) {
        const cLng = (Math.atan2(sy / n, sx / n) * 180) / Math.PI;
        const cLat = slat / n;
        if (Number.isFinite(cLng) && Number.isFinite(cLat)) {
          projection.rotate(AZIMUTHAL.includes(settings.projection.name) ? [-cLng, -cLat] : [-cLng, 0]);
        }
      }
    }

    if (height == null) {
      // Auto height must follow the FRAME's aspect when the map is framed (bbox/region), not the
      // whole sphere — otherwise the bbox is letterboxed in a world-tall canvas and the crop
      // (clipExtent) shows area outside the bbox. Fall back to the sphere for a whole-world render.
      // For a custom (satellite) projection the scale/translate are AUTHORITATIVE — refitting via
      // fitWidth would clobber the camera framing — so just default to a square canvas.
      if (settings.projection.type == "custom") {
        height = width;
      } else {
        const fitTarget =
          settings.bounds.bounder && settings.bounds.feature ? settings.bounds.feature : sphere;
        const [[x0, y0], [x1, y1]] = d3
          .geoPath(projection.fitWidth(width, fitTarget))
          .bounds(fitTarget);
        const dy = Math.ceil(y1 - y0),
          l = Math.min(Math.ceil(x1 - x0), dy);
        projection.scale((projection.scale() * (l - 1)) / l).precision(0.2);
        height = dy;
      }
    }

    if (settings.projection.fit == "none") {
    }

    if (!settings.bounds.bounder && settings.projection.type != "atlas") {
      if (settings.projection.fit == "iso2") {
        if (settings.bounds.countries.length > 0) {
          let list = settings.bounds.countries;
          let filteredCountries = BASEMAP.countries.filter(function (d, i) {
            if (list.indexOf(d.properties.ISO_A2) > -1) {
              return d;
            }
          });

          projection.fitSize(
            [width, height],
            turf.featureCollection(filteredCountries)
          );
        }
      }

      if (settings.projection.fit == "iso3") {
        if (settings.bounds.countries.length > 0) {
          let list = settings.bounds.countries;
          let filteredCountries = BASEMAP.countries.filter(function (d, i) {
            if (list.indexOf(d.properties.ISO_A3) > -1) {
              return d;
            }
          });

          projection.fitSize(
            [width, height],
            turf.featureCollection(filteredCountries)
          );
        }
      }

      if (settings.projection.fit == "size") {
        projection.fitSize([width, height], sphere);
      }
      if (settings.projection.fit == "extent") {
        projection.fitExtent(
          [
            [0, 0],
            [width, height]
          ],
          sphere
        );
      }
    }
    // A custom (satellite) projection is camera-driven, not bbox-fit: skip fitSize so a populated
    // extent (the pane mirrors its view into the bbox field) doesn't override the camera framing.
    if (settings.bounds.bounder && settings.projection.type != "atlas" && settings.projection.type != "custom") {
      projection.fitSize([width, height], settings.bounds.feature);
    }
    // Projection fine-tuning overrides (non-custom): apply user-supplied d3 setter attributes AFTER the
    // fit, so an explicit scale / rotate / center / clipAngle wins over the auto-framing. Custom
    // (satellite) bakes its overrides into the build (they must re-derive scale/yShift/preclip), so skip.
    if (settings.projection.type != "custom" && settings.projection.overrides) {
      for (const key in settings.projection.overrides) {
        const v = settings.projection.overrides[key];
        if (typeof projection[key] === "function") {
          try { projection[key](v); } catch (e) { console.warn("[mapa] projection override failed:", key, e.message); }
        }
      }
    }
    // Clip the fitted projection to the canvas when the map is framed
    // (bounds.bounder = a bbox/region): drops off-frame geometry from the export and
    // lets tiles prune. For a whole-world render (no frame) clipping is disabled —
    // clipping a pole-wrapping polygon (Antarctica) to the canvas can invert it.
    // A custom (satellite) projection is camera-driven: its canvas IS the frame, so always clip —
    // otherwise the tile machinery enumerates the whole unclipped hemisphere and hangs the browser.
    if (settings.bounds.bounder || settings.projection.type == "custom") {
      // Extend the clip by the buffer (margin) so geometry is generated in the bleed zone
      // beyond the frame; the #content group's clip-path hides it, but it's in the export
      // to release. margin 0 = clip exactly to the frame (no bleed).
      projection.clipExtent([
        [-margin, -margin],
        [width + margin, height + margin]
      ]);
    }
    if (settings.clipping.clip) {
      function viewport() {
        let n = 15;
        let p = -1 * margin;

        return {
          type: "Polygon",
          coordinates: [
            [
              ...Array.from({ length: n }, (_, t) => [
                p + ((width - p * 2) * t) / n,
                p
              ]),
              ...Array.from({ length: n }, (_, t) => [
                width - p,
                ((height - p * 2) * t) / n + p
              ]),
              ...Array.from({ length: n }, (_, t) => [
                p + ((width - p * 2) * (n - t)) / n,
                height - p
              ]),
              ...Array.from({ length: n }, (_, t) => [
                p,
                ((height - p * 2) * (n - t)) / n + p
              ]),
              [p, p]
            ].map((p) => projection.invert(p) ?? [NaN, NaN])
          ]
        };
      }
      let v = {
        type: "Polygon",
        coordinates: [
          viewport().coordinates[0]
            .filter(d => d != null)
            .map(d3.geoRotation(projection.rotate()))
        ]
      };
      let clipPolygon = d3.geoClipPolygon(v);
      projection.preclip(clipPolygon);
    }
    let path = d3.geoPath().projection(projection);

    // invert() returns null for canvas corners that fall past the globe's limb
    // (routine under a tilted satellite projection) — fall back so this dead-but-
    // eagerly-computed bbox can't throw on null[0].
    const _invCorner = (pt) => projection.invert(pt) || [NaN, NaN];
    const [nw, ne, se, sw] = [
      _invCorner([-margin, -margin]),
      _invCorner([width + margin, -margin]),
      _invCorner([width + margin, height + margin]),
      _invCorner([-margin, height + margin])
    ];

    const bbox = [
      Math.min(nw[0], sw[0]),
      Math.min(sw[1], se[1]),
      Math.max(ne[0], se[0]),
      Math.max(nw[1], ne[1])
    ];

    let rotation = settings.rotation.value;
    if (settings.rotation.value instanceof Array) {
      rotation = settings.rotation.value;
    } else {
      rotation = [settings.rotation.value, 0, 0];
    }
    if (settings.rotation.rotate) {
      projection.rotate(rotation);
    }

    let layers = settings.layers;
    const svgEl = DOMsvg(width, height);
    const frameClipId = `frame-clip-${uid}`;
    {
      // The frame (bbox) IS the clip. Always present so the export carries a recoverable
      // clip mask; a buffer (margin) just renders bleed content that sits under it.
      const ns = "http://www.w3.org/2000/svg";
      const defsEl = document.createElementNS(ns, "defs");
      const cpEl = document.createElementNS(ns, "clipPath");
      cpEl.setAttribute("id", frameClipId);
      const rEl = document.createElementNS(ns, "rect");
      rEl.setAttribute("width", width);
      rEl.setAttribute("height", height);
      cpEl.appendChild(rEl);
      defsEl.appendChild(cpEl);
      svgEl.insertBefore(defsEl, svgEl.firstChild);
      // NB: clip-path goes on the content <g> below, NOT the root <svg> — Illustrator only
      // imports a clip-path as a releasable clipping mask when it's on a group.
    }
    const graphic = d3
      .select(svgEl)
      .attr("id", "graphic")
      .attr("stroke-linejoin", "round");

    if (settings.graphic.background) {
      // For a clipped globe/satellite projection (type "custom"), paint the background as the
      // projected SPHERE so only the globe disk gets the colour — a full-canvas rect floods the
      // space around the globe blue. Flat projections keep the full-canvas rect (no regression).
      if (settings.projection.type === "custom") {
        graphic
          .insert("path", ":first-child")
          .attr("d", path({ type: "Sphere" }))
          .attr("fill", settings.graphic.background);
      } else {
        // Cover the buffer (margin) bleed too, not just the frame — otherwise a buffered export has
        // background only inside the frame and bare bleed around it. x/y offset negative by the margin.
        graphic
          .insert("rect", ":first-child")
          .attr("x", -margin)
          .attr("y", -margin)
          .attr("width", width + 2 * margin)
          .attr("height", height + 2 * margin)
          .attr("fill", settings.graphic.background);
      }
    }


    // All map content lives inside this clipped group so the frame (bbox) reads as a proper
    // clipping mask in Illustrator; a buffer just renders bleed that sits under the mask.
    const gcontent = graphic
      .append("g")
      .attr("id", "content")
      .attr("clip-path", `url(#${frameClipId})`);

    let graster = gcontent.append("g").attr("id", "tilelayer"); //bottom
    let gbasemap = gcontent.append("g").attr("id", "basemap");
    let glayer = gcontent.append("g").attr("id", "layers");
    let gscalebar = gcontent.append("g").attr("id", "scalebar");
    const tilePromises = [];  // per-tile-layer "composite done" promises → exposed as node.tilesReady

    if (settings.graphic.clipFeature) {
      const clipId = `graphic-clip-${uid}`;
      defs
        .append("clipPath")
        .attr("id", clipId)
        .append("path")
        .attr("d", path(settings.graphic.clipFeature));
      graphic.attr("clip-path", `url(#${clipId})`);
    }

    const gradientItems = Array.isArray(settings.graphic.gradient)
      ? settings.graphic.gradient
      : settings.graphic.gradient
      ? [settings.graphic.gradient]
      : [];

    let ggradient = gcontent
      .append("g")
      .attr("id", "gradient")
      .style("display", gradientItems.length ? null : "none");

    let gannotation = gcontent.append("g").attr("id", "annotations"); //top
    let ggrid = gcontent.append("g").attr("id", "grid");

    const defs = graphic.select("defs").empty()
      ? graphic.append("defs")
      : graphic.select("defs");

    gradientItems.forEach((g) => {
      const rect = ggradient
        .append("rect")
        .attr("class", "gradient")
        .attr("width", width)
        .attr("height", height)
        .attr("fill", g.fill ?? "none")
        .style("fill-opacity", g.opacity ?? 1)
        .style("mix-blend-mode", g.blendMode ?? "normal")
        .style("pointer-events", "none");

      if (g.clipFeature) {
        const clipId = `gradient-clip-${uid}-${Math.random()
          .toString(36)
          .substr(2, 4)}`;
        const clipPath = defs.append("clipPath").attr("id", clipId);

        if (g.invert) {
          clipPath
            .append("path")
            .attr("d", `M0,0 H${width} V${height} H0 Z ${path(g.clipFeature)}`)
            .attr("clip-rule", "evenodd");
        } else {
          clipPath.append("path").attr("d", path(g.clipFeature));
        }

        rect.attr("clip-path", `url(#${clipId})`);
      }
    });

    let ggraphic = gcontent
      .append("g")
      .attr("id", "overlays")
      .style("pointer-events", "none");

    drawRasterLayers({
      parent: graster, layerGroup: glayer, tilesLayer: settings.layer.tiles, rasterLayer: settings.layer.raster,
      projection, path, width, height, margin, uid, defs, isCustomProjection: settings.projection.type === "custom", tilePromises
    });

    drawScaleBar({ group: gscalebar, scalebar: settings.scalebar, projection, width, height });

    // Locator inset — a corner-anchored vector mini-map. Appended last into the bounder-clipped
    // content group so it sits on top, like the scalebar overlay. Uses its own coarse world.
    if (settings.inset) {
      drawInset({ parent: gcontent, inset: settings.inset, d3, width, height, defs, uid,
        mainProjection: projection, isSatellite: settings.projection.type === "custom", insetBasemap: INSET_BASEMAP });
    }

    if (settings.northArrow && settings.northArrow.show) {
      drawNorthArrow({ parent: gcontent, cfg: settings.northArrow, projection, width, height });
    }

    drawBasemap({ parent: gbasemap, basemap, BASEMAP, Layer, projection, path, width, height, margin });


    if (settings.layer.polys.show) {
      const margin = settings.clipping.margin || 0;
      const [minLng, minLat, maxLng, maxLat] =
        settings.bounds.feature.geometry.coordinates[0].reduce(
          (acc, [lng, lat]) => [
            Math.min(acc[0], lng),
            Math.min(acc[1], lat),
            Math.max(acc[2], lng),
            Math.max(acc[3], lat)
          ],
          [Infinity, Infinity, -Infinity, -Infinity]
        );
      const degPerPx = (maxLng - minLng) / settings.width;
      const marginDeg = margin * degPerPx;
      const buffer = 4; // degrees
      const bbox = [
        minLng - buffer,
        minLat - buffer,
        maxLng + buffer,
        maxLat + buffer
      ];
      for (let l in settings.layer.polys.data) {
        if (settings.layer.polys.data[l].show === false) continue;
        let geometry = settings.layer.polys.data[l].geometry;
        if (!geometry || (Array.isArray(geometry) && geometry.length === 0))
          continue;

        const tolerance = settings.layer.polys.data[l].simplify ?? settings.simplify;
        if (tolerance && Array.isArray(geometry)) {
          const clean = geometry.filter(
            (f) => f && f.geometry && f.geometry.type
          );
          geometry = turf.simplify(turf.featureCollection(clean), {
            tolerance,
            highQuality: false
          }).features;
        }

        new Layer({
          geometry,
          group: glayer,
          style: settings.layer.polys.data[l].style,
          type: settings.layer.polys.data[l].style.type ?? "null",
          path: path,
          filter: settings.layer.polys.data[l].filter ?? { show: false }
        }).add;
      }
    }

    function addGrid(grids, units, data) {
      if (grids.type == "graticule") {
        addGraticule(grids);
      }
    }

    function addGraticule(grids) {
      const graticule = d3
        .geoGraticule()
        .step([grids.step[0] || 10, grids.step[1] || 10]);

      ggrid
        .append("path")
        .datum(graticule)
        .attr("d", path)
        .attr("fill", "none")
        .attr("stroke", grids.style?.stroke || "#ccc")
        .attr("stroke-width", grids.style?.["stroke-width"] || 0.5)
        .attr("opacity", grids.style?.opacity || 1);
    }

    const { createAnnotationGroups, addPoints, addAnnotations } = createLabelRenderer({ gannotation, uid, projection, width, height, path, defs });

    if (settings.layer.points.show) {
      if (settings.layer.points.data.length > 0) {
        let groups = new Set(
          settings.layer.points.data.map((d) => d.group ?? d.class ?? "default")
        );
        createAnnotationGroups(groups);
        addPoints(settings.layer.points.data, {
          dirDefaults: settings.layer.points.dirDefaults
        });
      }
    }

    if (basemap.sphere.show) {
      const globeRect = {
        type: "Feature",
        geometry: {
          type: "Polygon",
          coordinates: [
            [
              [-180, -90],
              [-180, 90],
              [180, 90],
              [180, -90],
              [-180, -90]
            ]
          ]
        }
      };
      const s = settings.basemap.background.style;
      ggraphic
        .append("g")
        .attr("id", "globe")
        .selectAll("path")
        .data([globeRect])
        .join("path")
        .attr("stroke", s.stroke || "none")
        .attr("fill", s.fill || "none")
        .attr("opacity", s.opacity || "1")
        .attr("d", path);
    }



    gradients.forEach(
      ({
        id,
        type = "linear",
        x1,
        y1,
        x2,
        y2,
        cx,
        cy,
        r,
        fx,
        fy,
        from,
        to,
        stops,
        animate
      }) => {
        let g;
        if (type === "radial") {
          g = defs
            .append("radialGradient")
            .attr("id", id)
            .attr("cx", cx ?? "50%")
            .attr("cy", cy ?? "50%")
            .attr("r", r ?? "50%")
            .attr("fx", fx ?? cx ?? "50%")
            .attr("fy", fy ?? cy ?? "50%");
        } else {
          g = defs
            .append("linearGradient")
            .attr("id", id)
            .attr("x1", x1)
            .attr("y1", y1)
            .attr("x2", x2)
            .attr("y2", y2);
        }

        if (stops) {
          stops.forEach(({ offset, color, opacity }) => {
            g.append("stop")
              .attr("offset", offset)
              .attr("stop-color", color)
              .attr("stop-opacity", opacity ?? 1);
          });
        } else {
          g.append("stop").attr("offset", "0%").attr("stop-color", from);
          g.append("stop").attr("offset", "100%").attr("stop-color", to);
        }
        if (animate?.type === "rotate") {
          g.attr("gradientTransform", "rotate(0 0.5 0.5)");
          g.append("animateTransform")
            .attr("attributeName", "gradientTransform")
            .attr("type", "rotate")
            .attr("from", "0 0.5 0.5")
            .attr("to", "360 0.5 0.5")
            .attr("dur", animate.duration ?? "3s")
            .attr("repeatCount", "indefinite");
        }
      }
    );

    patterns.forEach((p) => {
      if (defs.node().querySelector(`#${p.id}`)) return;
      const tempSvg = p.animate ? animatePattern(p) : pattern(p);
      const patternEl = tempSvg.querySelector("pattern");
      patternEl.setAttribute("id", p.id);
      defs.node().appendChild(patternEl);
    });

    masks.forEach(({ id, gradient }) => {
      defs
        .append("mask")
        .attr("id", id)
        .append("rect")
        .attr("width", "100%")
        .attr("height", "100%")
        .attr("fill", `url(#${gradient})`);
    });
    patterns
      .filter((p) => p.animate)
      .forEach((p) => {
        const anims = defs
          .node()
          .querySelectorAll(`#${p.id} animateTransform, #${p.id} animate`);
        const rect = graphic.node().querySelector(`rect[fill='url(#${p.id})']`);
        if (rect && anims.length) {
          rect.addEventListener("mouseover", () =>
            anims.forEach((a) => a.beginElement())
          );
          rect.addEventListener("mouseout", () =>
            anims.forEach((a) => a.endElement())
          );
        }
      });

    filters.forEach((f) => {
      if (defs.node().querySelector(`#${f.id}`)) return;
      defs.node().appendChild(buildFilter(f));
    });

    const patFolder = settings.patterns.folder.replace(/\/?$/, "/");
    patternDefs.forEach(({ name, pw, ph, bg, bgOp, op }, id) => {
      const pat = defs.append("pattern").attr("id", id)
        .attr("patternUnits", "userSpaceOnUse").attr("width", pw).attr("height", ph);
      if (bg) pat.append("rect").attr("width", pw).attr("height", ph).attr("fill", bg)
        .attr("fill-opacity", bgOp === 1 ? null : bgOp);
      pat.append("image").attr("href", `${patFolder}${encodeURIComponent(name)}.png`)
        .attr("width", pw).attr("height", ph).attr("opacity", op === 1 ? null : op);
    });

    ensureGlobalStyles(styles);
    drawOverlay({ graphicSelection: graphic, parent: ggraphic, overlay: settings.overlay, width, height });

    // d3-svg-annotation callouts: their own group, appended last so it sits on top of everything
    // (content, inset, scalebar, north arrow, overlay).
    if (settings.layer.annotations?.show && settings.layer.annotations.data?.length) {
      addAnnotations(
        settings.layer.annotations.data,
        settings.layer.annotations.editMode,
        graphic.append("g").attr("id", "callouts"),
        settings.fonts?.annotations
      );
    }
    // Fonts panel → Labels: whatever it sets wins over the point types' label fonts (poi-types.json
    // writes e.g. label-font on every city label, which beat a font set only on the group).
    { const f = settings.fonts?.labels;
      if (f) {
        gannotation.attr("font-family", f.family || null).attr("font-weight", f.weight || null).attr("font-style", f.style || null);
        const t = gannotation.selectAll("text");
        if (f.family) t.style("font-family", f.family);
        if (f.weight) t.style("font-weight", f.weight);
        if (f.style) t.style("font-style", f.style);
      } }

    const _node = graphic.node();
    // Resolves once every tile layer's composite is drawn — the caller awaits this before showing
    // the SVG, so nothing renders until all layers are ready (no async pop-in / wrong order).
    _node.tilesReady = tilePromises.length ? Promise.all(tilePromises) : Promise.resolve();
    // Expose the fitted projection (artboard px ↔ lng/lat) so callers can invert screen rects back
    // to a geographic bbox — e.g. "crop to view" turns the output zoom rectangle into a new extent.
    _node.projection = projection;
    // The basemap-wide simplify tolerance this render used (° — resolved from "auto" when set), so the
    // Basemap panel can show what auto picked. Layers with their own tolerance used that instead.
    _node.basemapSimplify = basemapSimplifyTolerance(basemap, projection, width, height);
    return _node;
}


// ---- basemap data loader (call once at runtime; no data needed at import) ----

// Fix inverted polygon winding (classic Antarctica bug): a correctly-wound
// spherical feature has d3.geoArea < 2π. If it's larger, the ring is wound the wrong
// way and d3 fills its complement — so reverse the rings. Only touches inverted
// features; correct ones are left alone.
function reverseRings(geom) {
  if (!geom) return;
  if (geom.type === "Polygon") geom.coordinates.forEach((r) => r.reverse());
  else if (geom.type === "MultiPolygon")
    geom.coordinates.forEach((p) => p.forEach((r) => r.reverse()));
}
function fixWinding(features) {
  if (!Array.isArray(features)) return features;
  for (const f of features) {
    if (f && f.geometry && d3.geoArea(f) > 2 * Math.PI) reverseRings(f.geometry);
  }
  return features;
}
function decodeBasemap(json, rewind = true) {
  let features;
  if (json && json.type === "Topology") {
    const key = Object.keys(json.objects)[0];
    features = topojson.feature(json, json.objects[key]).features;
  } else if (json && json.type === "FeatureCollection") {
    features = json.features;
  } else if (Array.isArray(json)) {
    features = json; // already an array of features (e.g. from the fgb stream)
  } else {
    return []; // null / empty (e.g. a bbox that matched no features) — never null downstream
  }
  // rewind=false for legitimately-large polygons (e.g. the world ocean) whose >2π area
  // would trip the inside-out heuristic and flip them to their complement.
  return rewind ? fixWinding(features) : features;
}

// bbox (optional) = [W, S, E, N]. In prod it range-requests only the features inside that
// extent from the FlatGeobuf build; without a bbox, prod streams the whole layer.
export async function loadBasemapData(baseURL = "./files/", bbox = null, forceFgb = false, only = null) {
  // Which files + their rewind/filename quirks come from the one layer config (basemap-layers.js).
  let names = [...BASEMAP_FILES];
  // `only` (array of file stems) limits the load to the layers actually in use — a turned-off
  // basemap layer shouldn't fetch its data at all. null/empty = load everything (default).
  if (Array.isArray(only) && only.length) names = names.filter((n) => only.includes(n));
  const FILES = Object.fromEntries(
    BASEMAP_LAYERS.filter((l) => l.fileName).map((l) => [l.file, l.fileName]));
  // ocean.json is the real world-ocean polygon (~71% of the globe). Its winding is already
  // correct (sea = inside), so it must NOT go through the >2π rewind heuristic — that flips
  // it to the land complement and fills land with blue ("blue behind the land"). Config flags it
  // with rewind:false.
  const NO_REWIND = new Set(BASEMAP_LAYERS.filter((l) => l.rewind === false).map((l) => l.file));
  // Prod streams the FlatGeobuf build (files-fgb/*.fgb) — only the bbox's features via HTTP range
  // requests. Local dev keeps the whole JSON (already fast off disk). "Local" = localhost /
  // 127.0.0.1 / *.local / file://; anything else is prod.
  const host = (typeof location !== "undefined" && location.hostname) || "";
  const isLocal = host === "" || host === "localhost" || host === "127.0.0.1" || host.endsWith(".local");
  const useFgb = forceFgb || !isLocal;  // forceFgb lets you test the fgb path locally (?fgb)
  const fgbURL = baseURL.replace(/files\/?$/, "files-fgb/");
  const rect = (Array.isArray(bbox) && bbox.length === 4 && bbox.every(Number.isFinite))
    ? { minX: bbox[0], minY: bbox[1], maxX: bbox[2], maxY: bbox[3] } : null;
  let fgbDeserialize = null;
  if (useFgb) {
    try {
      const fgb = await import("flatgeobuf/lib/mjs/geojson.js");
      fgbDeserialize = fgb.deserialize;
    } catch (e) {
      console.warn("loadBasemapData: flatgeobuf load failed, falling back to JSON — " + e.message);
    }
  }
  const out = {};
  await Promise.all(
    names.map(async (name) => {
      const stem = FILES[name] ?? name;
      // Fail soft per file: a missing basemap layer just isn't populated, rather than
      // taking down the whole load.
      try {
        if (fgbDeserialize) {
          let features = [];
          if (rect) {
            // With a bbox: stream over HTTP range requests, only the extent's features.
            const gen = fgbDeserialize(fgbURL + stem + ".fgb", rect);
            for await (const f of gen) if (f) features.push(f);
          } else {
            // No bbox (satellite / whole-world): the URL form needs a rect, so fetch the whole
            // file and deserialize the bytes instead.
            const res = await fetch(fgbURL + stem + ".fgb");
            if (!res.ok) return;
            const fc = fgbDeserialize(new Uint8Array(await res.arrayBuffer()));
            features = fc && fc.features ? fc.features : (Array.isArray(fc) ? fc : []);
          }
          out[name] = decodeBasemap(features, !NO_REWIND.has(name));
        } else {
          const res = await fetch(baseURL + stem + ".json");
          if (!res.ok) return;
          out[name] = decodeBasemap(await res.json(), !NO_REWIND.has(name));
        }
      } catch (e) {
        console.warn("loadBasemapData: skipping " + name + " (" + e.message + ")");
      }
    })
  );
  BASEMAP = { ...BASEMAP, ...out };
  return out;
}

// Load the coarse world used by the locator inset. Separate from loadBasemapData because the
// inset needs the WHOLE world (a locator globe/flat map), not the bbox-streamed frame extent.
// v1 layers: inset-ocean.json (sea polygon) + inset-innerlines.json (coarse boundaries). Fails
// soft per file — a missing layer just isn't drawn; the inset still renders its frame + marker.
export async function loadInsetData(baseURL = "./files/") {
  const names = ["inset-ocean", "inset-innerlines"];
  const out = {};
  await Promise.all(
    names.map(async (name) => {
      const key = name.replace("inset-", "");
      try {
        const res = await fetch(baseURL + name + ".json");
        if (!res.ok) return;
        let json = await res.json();
        // decodeBasemap knows Topology / FeatureCollection / array. Normalize the other GeoJSON
        // shapes a hand-built coarse file might use: a bare GeometryCollection (what inset-innerlines
        // is), a single Feature, or a bare geometry → wrap as a FeatureCollection.
        if (json && json.type === "GeometryCollection" && Array.isArray(json.geometries)) {
          json = { type: "FeatureCollection", features: json.geometries.map((g) => ({ type: "Feature", properties: {}, geometry: g })) };
        } else if (json && json.type === "Feature") {
          json = { type: "FeatureCollection", features: [json] };
        } else if (json && json.type && json.coordinates) {
          json = { type: "FeatureCollection", features: [{ type: "Feature", properties: {}, geometry: json }] };
        }
        // geojson rewind to d3's winding (reverse:true = clockwise exterior). Hand-built files come
        // wound either way; this normalizes them all. Lines pass through untouched.
        const feats = decodeBasemap(json, false);
        out[key] = feats.map((f) => turf.rewind(f, { reverse: true }));
      } catch (e) {
        console.warn("loadInsetData: skipping " + name + " (" + e.message + ")");
      }
    })
  );
  // Coarse world land (world-atlas land-110m, ~55 KB) for the GLOBE inset. Proper spherical polygons —
  // unlike the sea-inside ocean sheet, they render stably at any rotation/zoom (the sheet drops island
  // holes non-deterministically under the spherical clip). Flat insets still use the ocean sheet.
  try {
    const res = await fetch(baseURL + "inset-land.json");
    if (res.ok) out.land = decodeBasemap(await res.json(), true);
  } catch (e) {
    console.warn("loadInsetData: skipping inset-land (" + e.message + ")");
  }
  INSET_BASEMAP = { ...INSET_BASEMAP, ...out };
  return out;
}


// ---------------------------------------------------------------------------
// refUid -> geometry, resolved against the loaded BASEMAP (the same decoded,
// winding-corrected geometry Mapa already renders). The mapa/files/ copies don't
// carry a literal `uid` property, so reconstruct it from shapeGroup/shapeName the
// exact way the pmtile pipeline did (dev/README.md), then match. Mirrors sandbox
// resolveRefUidGeometry, minus the PMTiles query. admin0=countries is part of the basemap;
// admin1=provinces and admin2 are not loaded by default — load them into BASEMAP first.
// A trailing `*` is a prefix wildcard (e.g. "admin1:nga_*").
// ---------------------------------------------------------------------------
const REFUID_STORE = { admin0: "countries", admin1: "provinces", admin2: "admin2" };
function normalizeUidPart(s) {
  return String(s ?? "")
    .normalize("NFD").replace(/[̀-ͯ]/g, "") // strip diacritics
    .toLowerCase().replace(/&/g, "and").replace(/,/g, "")
    .trim().replace(/\s+/g, "_");
}
function featureUid(layer, props = {}) {
  if (props.uid) return String(props.uid); // honour a literal uid if the file has one
  if (layer === "admin0") return "admin0:" + normalizeUidPart(props.shapeGroup);
  if (layer === "admin1" || layer === "admin2")
    return layer + ":" + normalizeUidPart((props.shapeGroup ?? "") + "_" + (props.shapeName ?? ""));
  return null;
}
export function resolveRefUid(refUids) {
  const features = [];
  for (const ref of refUids || []) {
    const [layer, rest = ""] = String(ref).split(/:(.+)/);
    const arr = BASEMAP[REFUID_STORE[layer]];
    if (!Array.isArray(arr)) {
      console.warn("[mapa] refUid: basemap for '" + layer + "' not loaded — skipped:", ref);
      continue;
    }
    const wild = rest.endsWith("*");
    const needle = wild ? rest.slice(0, -1) : rest;
    let hit = 0;
    for (const f of arr) {
      const uid = featureUid(layer, f.properties);
      if (!uid) continue;
      const tail = uid.slice(layer.length + 1); // drop "<layer>:" prefix
      if (wild ? tail.startsWith(needle) : tail === needle) { features.push(f); hit++; }
    }
    if (!hit) console.warn("[mapa] refUid matched nothing:", ref);
  }
  return { type: "FeatureCollection", features };
}

